     * start, in seconds.
     *
     * @default 0
     */
    loopStart: number;
    /**
     * Defines where in the audio buffer the replay should
     * stop, in seconds.
     *
     * @default 0
     */
    loopEnd: number;
    /**
     * An offset to the time within the audio buffer the playback
     * should begin, in seconds.
     *
     * @default 0
     */
