    constructor(camera: TCamera);
    /**
     * The light's view of the world.
     */
    camera: TCamera;
    /**
     * The intensity of the shadow. The default is `1`.
     * Valid values are in the range `[0, 1]`.
     *
     * @default 1
     */
    intensity: number;
