    waitForAtomicPresentation(ownerKey: string): Promise<boolean>;
    /**
     * 지정한 owner의 표시 그룹이 끝난 이유를 구분해 반환합니다.
     * 줌 전환으로 기존 tile이 폐기된 경우와 실제 표시 실패를 분리하여 외부 Feature 커밋이
