     * @param {string | number} mode 적용할 앱 제어 mode
     * @param {number | false} [duration] 각도 이동에 사용할 시간이며 ms 단위. 넘기지 않거나 false이면 즉시 적용
     */
    setMode(mode: string | number, duration?: number | false): void;
    /**
     * 상하 회전 범위를 기본값으로 즉시 되돌립니다.
