     */
    update(useCollision?: boolean, rePositionTarget?: boolean): boolean | undefined;
    /**
     * 현재 terrain 충돌 보정 사용 여부를 반환합니다.
     *
     * @returns {boolean} 충돌 보정을 사용하면 true
     */
