 * @typedef {object} U3dComponentPositionArriveEvent
 * @property {U3dComponentPositionArriveData} [data] 이동 요약 정보
 */
/**
 * 3D 지도 위에 배치되는 개별 모델 객체(컴포넌트)를 나타내는 클래스입니다. <br>
