    /**
     * 디버그용 3D 객체가 가진 자식을 모두 떼어 내고 그 GPU 자원을 해제합니다.
     *
     * @override
     *
     * @param {import('@UGroup').UGroup} debugObject 자원을 해제할 디버그 객체
     */
    override disposeDebugObject(debugObject: UGroup): void;
    #private;
}

