// 자동 생성 파일입니다. tutorial-official/scripts/build-monaco-types.mjs에서 생성합니다.
import {GeOnDT as GeOnDTRuntime} from './dist/GeOnDT.modules.js';

declare global {
    /** 예제 Runner가 전역으로 노출하는 GeOnDT Engine입니다. */
    const GeOnDT: typeof GeOnDTRuntime;

    /**
     * 예제 Source의 `initialize`가 받는 공통 실행 Context입니다.
     *
     * `tutorial-official/js/example-runtime.js`의 `createExampleContext`가 만드는 구조를 따른다.
     * 구조가 바뀌면 이 선언도 함께 고쳐야 한다.
     */
    type GeOnDTExampleContext = Readonly<{
        /** 지도 Engine 본체 */
        app: U3dApp;
        /** Manifest Runtime 설정값 */
        config: Readonly<Record<string, unknown>>;
        /** 예제가 직접 레이어를 만들 때 쓰는 공통 배경지도·지형 주소 */
        layerInfo: Readonly<{
            baseLayers: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
            terrain: Readonly<Record<string, unknown>>;
        }>;
        /** Runtime Config가 생성한 공통 레이어 */
        layers: Readonly<Record<string, unknown>>;
        /** 예제 UI를 붙일 DOM 요소 (root, rail, viewer) */
        elements: Readonly<Record<string, HTMLElement>>;
        /** Manifest imports로 불러온 외부 Module */
        modules: Readonly<Record<string, unknown>>;
        /** 예제 Source 목록 */
        sources: ReadonlyArray<Readonly<Record<string, unknown>>>;
        /** 예제 코드 참조 Token */
        sourceTokens: Readonly<Record<string, unknown>>;
        /** Runtime 상태값 */
        runtime: Readonly<Record<string, unknown>>;
        /** API Help 제어 객체 */
        apiHelp: unknown;
    }>;

    /**
     * 예제 Page와 Runner가 현재 실행 중인 지도 Engine을 전역으로 노출합니다.
     *
     * `interface Window`의 멤버는 이름만으로 참조할 수 없어서, 예제가 `app.flyTo()`처럼
     * 전역 이름으로 바로 쓰는 경우를 위해 전역 변수로도 선언한다.
     */
    const app: U3dApp;

    interface Window {
        GeOnDT: typeof GeOnDTRuntime;
        Union3D: typeof GeOnDTRuntime;
        app: U3dApp;
    }
}
